const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

const inputLines = [];

rl.on('line', (line) => {
    inputLines.push(line);
});

rl.on('close', () => {
    main();
});

class InputReader {
    constructor(lines) {
        this.lines = lines;
        this.lineIndex = 0;
        this.tokens = [];
        this.tokenIndex = 0;
    }

    next() {
        while (this.tokenIndex >= this.tokens.length) {
            const line = this.lines[this.lineIndex++];
            this.tokens = line.split(/\s+/).filter(s => s.length > 0);
            this.tokenIndex = 0;
        }
        return this.tokens[this.tokenIndex++];
    }

    nextInt() {
        return parseInt(this.next(), 10);
    }

    nextLong() {
        return BigInt(this.next());
    }
}

class Node {
    constructor(char, index, n) {
        this.char = char;
        this.index = index;
        this.nextArray = new Array(26).fill(null);
        this.hasCul = false;
        this.isSame = false;
        this.nextCount = 0;
        this.nextList = [];
        this.countArray = new Array(n).fill(0n);
    }

    toString() {
        return `${this.char}`;
    }

    addNext(index, node) {
        if (this.nextArray[index] === null) {
            this.nextCount++;
            this.nextArray[index] = node;
            this.nextList.push(node);
        }
    }
}

function find(node) {
    if (node.hasCul) {
        return;
    }

    node.countArray[0] += 1n;
    for (const next of node.nextList) {
        find(next);
        for (let i = 0; i < next.countArray.length; i++) {
            if (next.countArray[i] > 0n) {
                node.countArray[i + 1] += next.countArray[i];
            }
        }
    }

    node.hasCul = true;
}

function main() {
    const inputReader = new InputReader(inputLines);

    const n = inputReader.nextInt();
    const k = inputReader.nextLong();
    const str = inputReader.next();

    const letters = new Array(26).fill(false);
    const list = [];
    for (let i = 0; i < str.length; i++) {
        const char = str[i];
        const node = new Node(char, i, n);
        const code = char.charCodeAt(0) - 'a'.charCodeAt(0);
        if (letters[code]) {
            node.isSame = true;
        } else {
            letters[code] = true;
        }
        list.push(node);
    }

    for (let i = 0; i < list.length; i++) {
        const ai = list[i];
        for (let j = i + 1; j < list.length; j++) {
            const aj = list[j];
            const code = aj.char.charCodeAt(0) - 'a'.charCodeAt(0);
            ai.addNext(code, aj);
        }
    }

    for (const node of list) {
        find(node);
    }

    const totalCountArray = new Array(n).fill(0n);
    for (let i = 0; i < n; i++) {
        for (const node of list) {
            if (!node.isSame) {
                totalCountArray[i] += node.countArray[i];
            }
        }
    }

    let totalCost = 0n;
    let selectCount = 0n;
    for (let i = n - 1; i >= 0; i--) {
        if (selectCount + totalCountArray[i] < k) {
            totalCost += BigInt(n - 1 - i) * totalCountArray[i];
            selectCount += totalCountArray[i];
        } else {
            const over = (selectCount + totalCountArray[i]) - k;
            totalCost += BigInt(n - 1 - i) * (totalCountArray[i] - over);
            selectCount += (totalCountArray[i] - over);
            break;
        }
    }

    if (selectCount < k) {
        if (selectCount === k - 1n) {
            console.log((totalCost + BigInt(n)).toString());
        } else {
            console.log(-1);
        }
    } else {
        console.log(totalCost.toString());
    }
}
